"use client";
import { useEffect, useRef, useState } from "react";

const SECTIONS = [
    { id: "overview", label: "Overview" },
    { id: "capabilities", label: "Capabilities" },
    { id: "architecture", label: "Architecture" },
];

const AegisLogo = () => (
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" className="text-[#E0B0FF]">
        <path d="M12 2L3 7v10l9 5 9-5V7l-9-5z" stroke="currentColor" strokeWidth="1.5" fill="none" />
        <path d="M12 7L7 10v4l5 3 5-3v-4l-5-3z" stroke="currentColor" strokeWidth="1" fill="currentColor" fillOpacity="0.15" />
    </svg>
);

const DecorArrow = () => (
    <div className="absolute top-[30%] left-[20%] opacity-40 mix-blend-screen pointer-events-none hidden md:block" style={{ transform: "rotate(-15deg)" }}>
        <svg width="40" height="120" viewBox="0 0 40 120" fill="none" className="text-[#C084FC]">
            <path d="M20 0 L40 20 M20 0 L0 20" stroke="currentColor" strokeWidth="2" />
            <path d="M20 20 L40 40 M20 20 L0 40" stroke="currentColor" strokeWidth="2" opacity="0.6" />
            <path d="M20 40 L40 60 M20 40 L0 60" stroke="currentColor" strokeWidth="2" opacity="0.3" />
            <line x1="20" y1="0" x2="20" y2="80" stroke="currentColor" strokeWidth="2" strokeDasharray="4 4" opacity="0.5" />
        </svg>
    </div>
);

interface LandingViewProps {
    onEnterDashboard: () => void;
}

export default function LandingView({ onEnterDashboard }: LandingViewProps) {
    const [activeSection, setActiveSection] = useState("overview");
    const heroRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const els = document.querySelectorAll("[data-reveal]");
        const io = new IntersectionObserver(
            (entries) => {
                entries.forEach((e) => {
                    if (e.isIntersecting) {
                        (e.target as HTMLElement).style.opacity = "1";
                        (e.target as HTMLElement).style.transform = "translateY(0px) scale(1)";
                    }
                });
            },
            { threshold: 0.1 }
        );
        els.forEach((el) => io.observe(el));

        // Hero entrance
        if (heroRef.current) {
            setTimeout(() => {
                if (heroRef.current) {
                    heroRef.current.style.opacity = "1";
                    heroRef.current.style.transform = "scale(1)";
                }
            }, 100);
        }
        return () => io.disconnect();
    }, []);

    const scrollTo = (id: string) => {
        setActiveSection(id);
        document.getElementById(id)?.scrollIntoView({ behavior: "smooth" });
    };

    return (
        <div>
            {/* Nav */}
            <nav className="fixed top-0 left-0 right-0 z-50 h-20 flex items-center justify-between px-8"
                style={{ background: "rgba(15,17,23,0.6)", backdropFilter: "blur(16px)", borderBottom: "1px solid rgba(255,255,255,0.05)" }}>
                <div className="flex items-center gap-3">
                    <AegisLogo />
                    <button onClick={() => scrollTo("overview")} className="font-bold tracking-widest text-lg text-white hover:text-white cursor-pointer bg-transparent border-none">
                        AEGIS SRE
                    </button>
                </div>
                <div className="flex gap-8 text-sm font-medium text-gray-400">
                    {SECTIONS.map((s) => (
                        <button
                            key={s.id}
                            onClick={() => scrollTo(s.id)}
                            className={`relative cursor-pointer transition-colors hover:text-white bg-transparent border-none ${activeSection === s.id ? "text-white" : ""}`}
                        >
                            {s.label}
                            {activeSection === s.id && (
                                <div className="absolute -bottom-7 left-0 right-0 h-[2px] bg-gradient-to-r from-transparent via-[#E0B0FF] to-transparent" />
                            )}
                        </button>
                    ))}
                </div>
                <div className="w-[120px]" />
            </nav>

            {/* Hero */}
            <div className="relative w-full text-white">
                <section className="h-screen flex flex-col items-center justify-center w-full relative z-10 pt-20">
                    {/* Ambient radial bg */}
                    <div className="absolute inset-0 pointer-events-none" style={{
                        background: "radial-gradient(ellipse 60% 60% at 50% 40%, rgba(80,20,110,0.25) 0%, transparent 70%)"
                    }} />
                    <DecorArrow />
                    <div
                        ref={heroRef}
                        style={{ opacity: 0, transform: "scale(0.95)", transition: "opacity 0.9s cubic-bezier(.4,0,.2,1), transform 0.9s cubic-bezier(.4,0,.2,1)" }}
                        className="flex flex-col items-center"
                    >
                        <h1 className="text-7xl md:text-9xl font-extrabold tracking-tighter text-gradient mb-8 drop-shadow-2xl relative header-glow">
                            AEGIS SRE
                        </h1>
                        <p className="text-xl md:text-2xl text-muted max-w-2xl text-center mb-12 font-medium tracking-wide">
                            Enterprise Reliability Command System
                        </p>
                        <button
                            onClick={onEnterDashboard}
                            className="px-10 py-4 box-dna neon-highlight text-lg font-semibold tracking-wider transition-all text-[#FAFAFA] cursor-pointer hover:scale-105"
                            style={{ transition: "transform 0.2s ease" }}
                        >
                            Initialize Agent
                        </button>
                    </div>
                </section>

                {/* Fade separator */}
                <div className="w-full h-[120px] relative z-10" style={{
                    background: "linear-gradient(to bottom, rgba(15,17,23,0) 0%, rgba(15,17,23,0.6) 40%, #0F1117 100%)",
                    borderTop: "1px solid rgba(255,255,255,0.06)"
                }} />
            </div>

            {/* Overview */}
            <section id="overview" className="relative z-10 w-full">
                <div className="absolute inset-0 pointer-events-none" style={{
                    background: "radial-gradient(ellipse 70% 50% at 50% 40%, rgba(80,20,110,0.15) 0%, transparent 70%), linear-gradient(180deg, #080510 0%, #0C0816 30%, #090610 70%, #05030A 100%)",
                    zIndex: 0,
                }} />
                <div className="max-w-6xl mx-auto px-6 py-24 relative z-10">
                    <div className="flex flex-col gap-16">
                        <div className="w-full p-10 lg:p-14 box-dna texture-c" data-reveal
                            style={{ opacity: 0, transform: "translateY(30px)", transition: "all 0.8s cubic-bezier(.4,0,.2,1)" }}>
                            <div className="flex flex-col lg:flex-row lg:items-center gap-8">
                                <div className="flex-1">
                                    <div className="text-xs font-mono uppercase tracking-[0.3em] text-[#C084FC]/80 mb-4">Observe</div>
                                    <h2 className="text-2xl md:text-3xl font-bold header-glow mb-3 tracking-tight text-white">Real-Time Telemetry</h2>
                                    <p className="text-muted leading-relaxed max-w-lg">Monitor telemetry, traces, and critical metrics across the entire architectural stack with sub-second precision.</p>
                                </div>
                                <div className="shrink-0 text-right">
                                    <span className="text-xs font-mono uppercase tracking-wider text-[#C084FC] block neon-highlight">99.999% SLA Uptime</span>
                                </div>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                            <div className="lg:col-span-7 p-10 lg:p-14 box-dna texture-b" data-reveal
                                style={{ opacity: 0, transform: "translateY(30px)", transition: "all 0.8s cubic-bezier(.4,0,.2,1) 0.1s" }}>
                                <div className="text-xs font-mono uppercase tracking-[0.3em] text-[#C084FC]/80 mb-4">Reason</div>
                                <h2 className="text-2xl md:text-3xl font-bold header-glow mb-3 tracking-tight text-white">LLM-Powered Root Cause Analysis</h2>
                                <p className="text-muted leading-relaxed max-w-lg">Automate root cause analysis with LLM-powered insights, correlating spikes and anomalies instantaneously.</p>
                                <div className="mt-6"><span className="text-xs font-mono uppercase tracking-wider text-[#C084FC] neon-highlight">&lt; 200ms Inference</span></div>
                            </div>
                            <div className="lg:col-span-5 p-10 flex flex-col justify-center box-dna texture-a" data-reveal
                                style={{ opacity: 0, transform: "translateY(30px)", transition: "all 0.8s cubic-bezier(.4,0,.2,1) 0.2s" }}>
                                <div className="text-xs font-mono uppercase tracking-[0.3em] text-[#C084FC]/80 mb-4">Act</div>
                                <h2 className="text-2xl font-bold header-glow mb-3 tracking-tight text-white">Autonomous Remediation</h2>
                                <p className="text-muted leading-relaxed">Execute remediation workflows, scale infrastructure, or rollback deployments seamlessly.</p>
                                <div className="mt-6"><span className="text-xs font-mono uppercase tracking-wider text-[#C084FC] neon-highlight">0 Human Interventions</span></div>
                            </div>
                        </div>
                    </div>
                </div>
            </section>

            {/* Capabilities */}
            <section id="capabilities" className="relative w-full text-white overflow-x-hidden">
                <div className="absolute inset-0 pointer-events-none" style={{
                    background: "radial-gradient(ellipse 70% 50% at 50% 40%, rgba(80,20,110,0.15) 0%, transparent 70%), linear-gradient(180deg, #080510 0%, #0C0816 30%, #090610 70%, #05030A 100%)",
                    zIndex: 0,
                }} />
                <div className="relative z-10 pt-24 pb-20 px-8" data-reveal
                    style={{ opacity: 0, transform: "translateY(40px)", transition: "all 0.8s cubic-bezier(.4,0,.2,1)" }}>
                    <div className="max-w-5xl mx-auto text-center">
                        <h1 className="text-6xl md:text-8xl font-extrabold tracking-tighter text-gradient mb-6 drop-shadow-2xl header-glow">Capabilities</h1>
                        <p className="text-lg md:text-xl text-muted max-w-2xl mx-auto tracking-wide font-medium">Autonomous reliability — from signal ingestion to self-healing infrastructure</p>
                    </div>
                </div>

                {/* Cap 01 */}
                <div className="relative z-10 px-8 mb-32" data-reveal
                    style={{ opacity: 0, transform: "translateY(40px)", transition: "all 0.8s cubic-bezier(.4,0,.2,1) 0.1s" }}>
                    <div className="w-full max-w-7xl mx-auto box-dna texture-a">
                        <div className="flex flex-col lg:flex-row min-h-[420px]">
                            <div className="flex-1 p-12 lg:p-16 flex flex-col justify-center">
                                <div className="text-xs font-mono uppercase tracking-[0.3em] text-primary/60 mb-6">01 — Observe</div>
                                <h2 className="text-3xl md:text-4xl font-bold tracking-tight text-white mb-6 leading-[1.15] header-glow">Telemetry Ingestion<br /><span className="text-gray-500">&amp; Anomaly Detection</span></h2>
                                <p className="text-muted leading-relaxed max-w-lg mb-8">AEGIS absorbs millions of signals per second — traces, metrics, logs, and events — feeding them through a multi-layered anomaly detection mesh. Temporal pattern recognition surfaces deviations before they cascade into outages.</p>
                                <div className="flex gap-12 text-sm font-mono">
                                    {[["1.2M", "Events / sec"], ["<50ms", "Detection latency"], ["99.97%", "Precision"]].map(([val, label]) => (
                                        <div key={label}>
                                            <div className="text-[#E0B0FF] text-2xl font-bold mb-1">{val}</div>
                                            <div className="text-gray-500 uppercase tracking-wider text-xs">{label}</div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                            <div className="flex-1 relative min-h-[300px] lg:min-h-0 overflow-hidden">
                                <div className="absolute inset-0" style={{
                                    background: "radial-gradient(ellipse 60% 40% at 60% 50%, rgba(224,176,255,0.06) 0%, transparent 70%)"
                                }} />
                                <div className="absolute top-16 right-12 w-[180px] h-[120px] rounded-2xl" style={{
                                    background: "linear-gradient(145deg, rgba(224,176,255,0.04) 0%, rgba(74,14,96,0.08) 100%)",
                                    border: "1px solid rgba(224,176,255,0.06)"
                                }} />
                                <div className="absolute bottom-20 right-24 w-[140px] h-[200px] rounded-2xl" style={{
                                    background: "linear-gradient(160deg, rgba(224,176,255,0.03) 0%, rgba(15,17,23,0.4) 100%)",
                                    border: "1px solid rgba(255,255,255,0.04)"
                                }} />
                                <div className="absolute inset-x-0 h-px opacity-20" style={{
                                    background: "linear-gradient(90deg, transparent 0%, #E0B0FF 50%, transparent 100%)",
                                    top: "60%"
                                }} />
                            </div>
                        </div>
                    </div>
                </div>

                {/* Cap 02 */}
                <div className="relative z-10 px-8 mb-32" data-reveal
                    style={{ opacity: 0, transform: "translateY(40px)", transition: "all 0.8s cubic-bezier(.4,0,.2,1) 0.1s" }}>
                    <div className="max-w-7xl mx-auto">
                        <div className="text-xs font-mono uppercase tracking-[0.3em] text-primary/60 mb-6 px-2">02 — Reason</div>
                        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                            <div className="lg:col-span-7 p-12 lg:p-14 flex flex-col justify-between min-h-[400px] box-dna texture-b">
                                <div className="relative z-10">
                                    <h2 className="text-3xl md:text-4xl font-bold tracking-tight text-white mb-5 leading-[1.15] header-glow">Root Cause Reasoning<br /><span className="text-gray-500">&amp; Signal Correlation</span></h2>
                                    <p className="text-muted leading-relaxed max-w-md">LLM-powered reasoning engine cross-references telemetry streams, deployment manifests, and historical incident data to isolate root causes with surgical accuracy.</p>
                                </div>
                                <div className="relative z-10 flex gap-10 mt-8 text-sm font-mono">
                                    {[["94%", "Accuracy"], ["<200ms", "Inference"]].map(([val, label]) => (
                                        <div key={label}>
                                            <div className="text-[#E0B0FF] text-xl font-bold mb-1">{val}</div>
                                            <div className="text-gray-500 uppercase tracking-wider text-xs">{label}</div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                            <div className="lg:col-span-5 flex flex-col gap-6">
                                <div className="p-10 flex-[1.3] flex flex-col justify-center box-dna texture-c">
                                    <h3 className="text-xl font-bold text-white mb-3 header-glow">Multi-Hop Causal Chains</h3>
                                    <p className="text-muted text-sm leading-relaxed">Traces correlation paths across distributed services, linking upstream triggers to downstream failures through temporal and topological analysis.</p>
                                </div>
                                <div className="p-10 flex-[0.7] flex flex-col justify-center box-dna texture-a">
                                    <h3 className="text-xl font-bold text-white mb-3 header-glow">Historical Context</h3>
                                    <p className="text-muted text-sm leading-relaxed">Every hypothesis is enriched with incident memory — past resolutions, outcome effectiveness, and failure mode patterns.</p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Cap 03 */}
                <div className="relative z-10 px-8 mb-32" data-reveal
                    style={{ opacity: 0, transform: "translateY(40px)", transition: "all 0.8s cubic-bezier(.4,0,.2,1) 0.1s" }}>
                    <div className="max-w-7xl mx-auto">
                        <div className="text-xs font-mono uppercase tracking-[0.3em] text-primary/60 mb-6 px-2">03 — Act</div>
                        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                            <div className="lg:col-span-5 p-12 flex flex-col justify-center min-h-[480px] box-dna texture-b">
                                <h2 className="text-3xl md:text-4xl font-bold tracking-tight text-white mb-5 leading-[1.15] header-glow">Autonomous<br /><span className="text-gray-500">Remediation</span></h2>
                                <p className="text-muted leading-relaxed mb-8">AEGIS doesn&#39;t just diagnose — it acts. Approved remediation workflows execute infrastructure-level operations: process termination, resource scaling, deployment rollbacks, and configuration hot-patches.</p>
                                <div className="flex flex-col gap-4">
                                    {["Process Lifecycle Management", "Horizontal & Vertical Scaling", "Deployment Rollback Chains", "Config Hot-Patch Execution"].map((item) => (
                                        <div key={item} className="flex items-center gap-3 group">
                                            <div className="w-1.5 h-1.5 rounded-full bg-[#E0B0FF]/40 group-hover:bg-[#E0B0FF] transition-colors" />
                                            <span className="text-sm text-gray-300 tracking-wide">{item}</span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                            <div className="lg:col-span-7 min-h-[480px] box-dna texture-c" style={{ position: "relative" }}>
                                <div className="absolute top-12 left-10 right-10 flex flex-col gap-3">
                                    {[["DETECT", "85%"], ["ANALYZE", "70%"], ["PROPOSE", "55%"], ["EXECUTE", "40%"]].map(([label, w]) => (
                                        <div key={label} className="flex items-center gap-4">
                                            <div className="h-12 rounded-xl flex items-center px-5" style={{ width: w, background: "linear-gradient(90deg, rgba(192,132,252,0.06) 0%, rgba(74,14,96,0.08) 100%)", border: "1px solid rgba(192,132,252,0.08)" }}>
                                                <span className="text-xs font-mono uppercase tracking-[0.25em] text-gray-500">{label}</span>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                                <div className="absolute bottom-10 left-10 right-10 flex gap-10 text-sm font-mono">
                                    {[["0", "Human Interventions"], ["<4s", "Mean Time to Remediate"]].map(([val, label]) => (
                                        <div key={label}>
                                            <div className="text-[#E0B0FF] text-xl font-bold mb-1">{val}</div>
                                            <div className="text-gray-500 uppercase tracking-wider text-xs">{label}</div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </section>

            {/* Architecture */}
            <section id="architecture" className="relative w-full text-white overflow-x-hidden">
                <div className="absolute inset-0 pointer-events-none" style={{
                    background: "radial-gradient(ellipse 70% 50% at 50% 40%, rgba(80,20,110,0.15) 0%, transparent 70%), linear-gradient(180deg, #080510 0%, #0C0816 30%, #090610 70%, #05030A 100%)",
                    zIndex: 0,
                }} />
                <div className="relative z-10 pt-24 pb-20 px-8" data-reveal
                    style={{ opacity: 0, transform: "translateY(40px)", transition: "all 0.8s cubic-bezier(.4,0,.2,1)" }}>
                    <div className="max-w-5xl mx-auto text-center">
                        <h1 className="text-6xl md:text-8xl font-extrabold tracking-tighter text-gradient mb-6 drop-shadow-2xl header-glow">Architecture</h1>
                        <p className="text-lg md:text-xl text-muted max-w-2xl mx-auto tracking-wide font-medium">Five-tier autonomous reliability pipeline — from raw signal to closed-loop healing</p>
                    </div>
                </div>

                <div className="relative z-10 px-8 mb-24">
                    <div className="max-w-6xl mx-auto relative">
                        <div className="absolute left-1/2 top-0 bottom-0 w-px -translate-x-1/2 hidden lg:block" style={{
                            background: "linear-gradient(180deg, rgba(224,176,255,0.0) 0%, rgba(224,176,255,0.12) 10%, rgba(224,176,255,0.08) 50%, rgba(224,176,255,0.12) 90%, rgba(224,176,255,0.0) 100%)"
                        }} />

                        {[
                            { tier: "01", side: "left", texture: "texture-c", title: "Data Sources", desc: "Application logs, infrastructure metrics, distributed traces, deployment events, and configuration state changes stream continuously from your production environment." },
                            { tier: "02", side: "right", texture: "texture-b", title: "Ingestion & Streaming", desc: "High-throughput ingestion pipeline normalizes, enriches, and routes signals through a real-time streaming mesh. Schema-aware parsing ensures consistency across heterogeneous telemetry formats." },
                            { tier: "03", side: "left", texture: "texture-c", title: "Reasoning & Correlation", desc: "LLM-powered reasoning engine performs multi-hop causal inference across correlated signal clusters. Temporal pattern matching and topological analysis isolate root causes within milliseconds." },
                            { tier: "04", side: "right", texture: "texture-b", title: "Execution & Control", desc: "Validated remediation plans dispatch through an execution gateway with configurable approval policies. Infrastructure-as-code operations execute atomically with automatic rollback safety nets." },
                            { tier: "05", side: "left", texture: "texture-c", title: "Feedback & Observability Loop", desc: "Post-action effectiveness is measured against baseline SLIs. Outcomes feed back into the reasoning model, continuously improving accuracy and reducing false-positive rates over time." },
                        ].map(({ tier, side, texture, title, desc }, i) => (
                            <div key={tier} className={`relative mb-16`} data-reveal
                                style={{ opacity: 0, transform: "translateY(40px)", transition: `all 0.8s cubic-bezier(.4,0,.2,1) ${i * 0.1}s` }}>
                                <div className="absolute left-1/2 top-8 -translate-x-1/2 hidden lg:flex flex-col items-center">
                                    <div className="w-3 h-3 rounded-full border-2" style={{
                                        borderColor: "rgba(224,176,255,0.3)",
                                        background: i === 2 ? "rgba(224,176,255,0.5)" : "rgba(224,176,255,0.15)",
                                        boxShadow: i === 2 ? "0 0 12px rgba(224,176,255,0.3)" : "none"
                                    }} />
                                    {i < 4 && <div className="mt-1 text-[#E0B0FF]/20 text-xs">▼</div>}
                                </div>
                                <div className={`w-full lg:w-[55%] p-10 lg:p-14 box-dna ${texture} ${side === "right" ? "lg:ml-auto" : "lg:mr-auto"}`}>
                                    <div className="relative z-10">
                                        <div className="text-xs font-mono uppercase tracking-[0.3em] text-primary/80 mb-4">{tier} — Tier</div>
                                        <h3 className="text-2xl md:text-3xl font-bold tracking-tight text-white mb-4 header-glow">{title}</h3>
                                        <p className="text-muted leading-relaxed max-w-lg">{desc}</p>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* System Overview */}
                <div className="relative z-10 px-8 mb-32" data-reveal
                    style={{ opacity: 0, transform: "translateY(40px)", transition: "all 0.8s cubic-bezier(.4,0,.2,1)" }}>
                    <div className="max-w-7xl mx-auto">
                        <div className="text-xs font-mono uppercase tracking-[0.3em] text-primary/60 mb-6 px-2">System Overview</div>
                        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                            <div className="lg:col-span-8 p-12 lg:p-14 min-h-[350px] flex flex-col justify-between box-dna texture-a">
                                <div className="relative z-10">
                                    <h2 className="text-3xl md:text-4xl font-bold tracking-tight text-white mb-5 leading-[1.15] header-glow">Closed-Loop<br /><span className="text-gray-500">Reliability Engine</span></h2>
                                    <p className="text-muted leading-relaxed max-w-xl">AEGIS operates as a continuous feedback system. Every remediation outcome refines the reasoning model. Anomaly baselines adapt to infrastructure drift. The platform becomes more precise with every incident it processes.</p>
                                </div>
                                <div className="relative z-10 flex gap-10 mt-8 text-sm font-mono">
                                    {[["5", "Processing Tiers"], ["∞", "Feedback Loops"], ["<12s", "End-to-End Cycle"]].map(([val, label]) => (
                                        <div key={label}>
                                            <div className="text-primary text-xl font-bold mb-1 neon-highlight">{val}</div>
                                            <div className="text-gray-500 uppercase tracking-wider text-xs">{label}</div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                            <div className="lg:col-span-4 flex flex-col gap-6">
                                <div className="p-10 flex-[1.4] flex flex-col justify-center box-dna texture-b">
                                    <h3 className="text-xl font-bold text-white mb-3 header-glow">Extensible Pipeline</h3>
                                    <p className="text-muted text-sm leading-relaxed">Every tier exposes plugin interfaces — custom anomaly detectors, bespoke reasoning modules, and organization-specific remediation playbooks integrate seamlessly.</p>
                                </div>
                                <div className="p-10 flex-[0.6] flex flex-col justify-center box-dna texture-c">
                                    <h3 className="text-xl font-bold text-white mb-3 header-glow">Zero-Trust Execution</h3>
                                    <p className="text-muted text-sm leading-relaxed">All remediation actions traverse an audit gateway with cryptographic provenance and approval chain verification.</p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Footer */}
                <div className="relative z-10 h-32" />
                <footer className="relative z-10 border-t border-white/5 px-8 py-10">
                    <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-4">
                        <div className="flex items-center gap-3">
                            <AegisLogo />
                            <span className="font-bold tracking-widest text-sm text-white/60">AEGIS SRE</span>
                        </div>
                        <p className="text-xs text-muted">Enterprise Reliability Command System &mdash; Autonomous Infrastructure Intelligence</p>
                        <button
                            onClick={onEnterDashboard}
                            className="text-xs text-[#C084FC]/80 hover:text-[#C084FC] transition-colors font-mono uppercase tracking-wider"
                        >
                            Enter Dashboard →
                        </button>
                    </div>
                </footer>
            </section>
        </div>
    );
}
